contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes32 hash, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount == 1 ether);
        bool settle0Reverted;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { settle0Reverted = true; } else { settle0Reverted = false; }
        bool lockReverted;
        c.lockInGuess{value: amount}(hash); bool __rev1 = __ESBMC_reverted(); if (__rev1) { lockReverted = true; } else { lockReverted = false; }
        bool settle1Reverted;
        c.settle(); bool __rev2 = __ESBMC_reverted(); if (__rev2) { settle1Reverted = true; } else { settle1Reverted = false; }
        assert(settle0Reverted && !lockReverted && settle1Reverted);
    }
    receive() external payable {}
}

