// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 hash, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        amount = 1 ether;
        bool settle0Reverted;
        try c.settle() { settle0Reverted = false; } catch { settle0Reverted = true; }
        bool lockReverted;
        try c.lockInGuess{value: amount}(hash) { lockReverted = false; } catch { lockReverted = true; }
        bool settle1Reverted;
        try c.settle() { settle1Reverted = false; } catch { settle1Reverted = true; }
        assertTrue(settle0Reverted && !lockReverted && settle1Reverted);
    }

    function testFuzz_run(bytes32 hash, uint256 amount) public {
        _run(hash, amount);
    }

    receive() external payable {}
}
